    "summary": "Securely update project runtime config set secrets",
    "operationId": "updateProjectRuntimeConfigSetRuntimeSecrets",
    "requestBody": {
      "required": true,
      "contentTypes": [
        "application/json"
      ],
      "schemaRefs": [
        "#/components/schemas/DeploymentTargetRuntimeSecretsInput"
      ]
    },
    "inputSchema": {
      "type": "object",
      "properties": {
        "projectId": {
          "type": "string"
        },
        "setId": {
          "type": "string"
        },
        "body": {
          "ref": "#/components/schemas/DeploymentTargetRuntimeSecretsInput",
          "type": "object",
          "required": [
            "items"
          ],
          "properties": {
            "items": {
              "type": "array",
              "items": {
                "ref": "#/components/schemas/RuntimeSecretMutationItem",
                "type": "object",
                "required": [
                  "key",
                  "operation",
                  "valueMode"
                ],
                "properties": {
                  "generation": {
                    "type": "object",
                    "properties": {
                      "encoding": {
                        "type": "string",
                        "enum": [
                          "base64",
                          "hex",
                          "alphanumeric",
                          "numeric"
                        ],
                        "default": "base64"
                      },
                      "length": {
                        "type": "integer",
                        "default": 32,
                        "minimum": 8,
                        "maximum": 256
                      }
                    },
                    "additionalProperties": false
                  },
                  "key": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 128,
                    "pattern": "^[A-Za-z_][A-Za-z0-9_]*$"
                  },
                  "operation": {
                    "type": "string",
                    "enum": [
                      "set",
                      "generate",
                      "clear"
                    ]
                  },
                  "value": {
                    "type": "string",
                    "description": "Used only by set. Empty values retain the existing secret.",
                    "writeOnly": true,
                    "maxLength": 8192
                  },
                  "valueMode": {
                    "type": "string",
                    "enum": [
                      "secret"
                    ]
                  }
                },
                "additionalProperties": false
              },
              "minItems": 1,
              "maxItems": 128
            }
          },
          "additionalProperties": false
        }
      },
      "required": [
        "body",
        "projectId",
        "setId"
      ],
      "additionalProperties": false
    },
    "outputSchema": {
      "ref": "#/components/schemas/DeploymentTargetRuntimeSecretsResponse",
      "type": "object",
      "required": [
        "clearedKeys",
        "configuredKeys",
        "environmentVariables",
        "generatedKeys"
      ],
      "properties": {
        "clearedKeys": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "configuredKeys": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "environmentVariables": {
          "type": "array",
          "items": {
            "ref": "#/components/schemas/RuntimeEnvironmentVariable",
            "type": "object",
            "description": "One stored runtime environment value mode. Responses may contain public and secret entries with the same key; the secret entry takes precedence in deployed workloads.",
            "required": [
              "configured",
              "key",
              "valueMode"
            ],
            "properties": {
              "configured": {
                "type": "boolean"
              },
              "key": {
                "type": "string",
                "minLength": 1,
                "maxLength": 128,
                "pattern": "^[A-Za-z_][A-Za-z0-9_]*$"
              },
              "value": {
                "type": "string",
                "description": "Present only for public variables. Secret values and storage references are never returned."
              },
              "valueMode": {
                "type": "string",
                "enum": [
                  "public",
                  "secret"
                ]
              }
            },
            "additionalProperties": false
          }
        },
        "generatedKeys": {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      },
      "additionalProperties": false
    },
